    EMIT("\"%s\":%ju,", "max_streams",
        (uintmax_t)obj->max_streams);
    EMIT("\"%s\":", "mem_pressure");
    EMIT_SUB(json_conf_mux_mem_pressure_marshal, &obj->mem_pressure);
